//! 变量系统集成测试
//!
//! 覆盖 callScene 局部变量传参, return 返回值写回, 场景自然结束的默认返回值,
//! 以及 setVar 始终写入普通变量 (基底层) 的 WebGAL 语义.

use std::collections::HashMap;

use webgal_language_core::{element::AnimationList, resource::Config, sentence::Scene};
use webgal_simulate::{DiagnosticKind, ProjectView, StopReason, simulate};

/// 测试项目视图
struct TestProject {
    config: Config,
    scenes: HashMap<String, Scene>,
}

impl<'a> ProjectView<'a> for &'a TestProject {
    fn get_config(&self) -> &'a Config {
        &self.config
    }

    fn get_scene(&self, path: &str) -> Option<&'a Scene> {
        self.scenes.get(path)
    }

    fn iter_scenes(&self) -> impl Iterator<Item = (String, &'a Scene)> + Send {
        self.scenes
            .iter()
            .map(|(path, scene)| (path.clone(), scene))
    }

    fn get_animation(&self, _name: &str) -> Option<&'a AnimationList> {
        None
    }
}

/// 构建测试项目
fn project(config: &str, scenes: &[(&str, &str)]) -> TestProject {
    TestProject {
        config: Config::from_str(config),
        scenes: scenes
            .iter()
            .map(|&(path, content)| (path.to_string(), Scene::from_str(content)))
            .collect(),
    }
}

/// 收集全部诊断
fn diagnostics(project: &TestProject) -> Vec<DiagnosticKind> {
    simulate(project)
        .into_iter()
        .flat_map(|(_, diagnostics)| diagnostics.into_iter().map(|d| d.detail))
        .collect()
}

/// 是否存在包含指定错误文本的表达式错误
fn has_error(kinds: &[DiagnosticKind], needle: &str) -> bool {
    kinds.iter().any(
        |kind| matches!(kind, DiagnosticKind::ExpressionError(_, error) if error.contains(needle)),
    )
}

// -------- callScene 局部变量传参 --------

#[test]
fn call_scene_passes_locals_and_return_value() {
    let project = project(
        "",
        &[
            (
                "start.txt",
                "callScene:sub.txt -hp=100 -name=1 -writeReturnTo=ret;\n\
                 :ret_ok -when=(1/(ret-99)>0);\n\
                 :name_gone -when=(name==1);",
            ),
            (
                "sub.txt",
                ":local_hp -when=(1/(hp-100)>0);\n\
                 :local_name -when=(1/(name-1)>0);\n\
                 return:99;",
            ),
        ],
    );
    let kinds = diagnostics(&project);

    // 局部变量在子场景内可见
    assert!(
        has_error(&kinds, "除数不能为零"),
        "局部变量 hp=100 不可见: {kinds:?}"
    );
    assert!(
        has_error(&kinds, "除数不能为零"),
        "局部变量 name=1 不可见: {kinds:?}"
    );
    // return 返回值写回 writeReturnTo 目标
    assert!(
        has_error(&kinds, "除数不能为零"),
        "返回值 ret=99 未写回: {kinds:?}"
    );
    // 返回后局部变量消失
    assert!(
        has_error(&kinds, "变量 `name` 未定义"),
        "返回后局部变量仍可见: {kinds:?}"
    );
}

#[test]
fn call_scene_evaluates_locals_in_caller_scope() {
    let project = project(
        "",
        &[
            ("start.txt", "setVar:hp=100;\ncallScene:sub.txt -x=hp+1;"),
            ("sub.txt", ":x_ok -when=(1/(x-101)>0);"),
        ],
    );
    let kinds = diagnostics(&project);

    // 传参表达式在调用方作用域求值, x = hp + 1 = 101
    assert!(
        has_error(&kinds, "除数不能为零"),
        "传参未在调用方作用域求值: {kinds:?}"
    );
}

// -------- 变量写入与遮蔽 --------

#[test]
fn set_var_writes_base_not_locals() {
    let project = project(
        "",
        &[
            (
                "start.txt",
                "setVar:hp=50;\ncallScene:shadow.txt -hp=100;\n:base_updated -when=(1/(hp-200)>0);",
            ),
            (
                "shadow.txt",
                "setVar:hp=200;\n:local_shadow -when=(1/(hp-100)>0);",
            ),
        ],
    );
    let kinds = diagnostics(&project);

    // setVar 写入基底层, 但读取仍遵循查找链 (局部变量遮蔽普通变量)
    assert!(
        has_error(&kinds, "除数不能为零"),
        "setVar 后局部变量遮蔽失效: {kinds:?}"
    );
    // 返回后基底层被 setVar 更新为 200
    assert!(
        has_error(&kinds, "除数不能为零"),
        "setVar 未写入基底层: {kinds:?}"
    );
}

// -------- 场景自然结束与顶层 return --------

#[test]
fn natural_scene_end_writes_empty_return_value() {
    let project = project(
        "",
        &[
            (
                "start.txt",
                "callScene:nat.txt -writeReturnTo=nret;\n:nret_written -when=(nret==1);",
            ),
            ("nat.txt", "done;"),
        ],
    );
    let kinds = diagnostics(&project);

    // 自然结束时 writeReturnTo 收到空字符串, 与数字 1 比较产生类型错误
    assert!(
        has_error(&kinds, "类型不一致"),
        "自然结束未写回返回值: {kinds:?}"
    );
    assert!(
        !has_error(&kinds, "变量 `nret` 未定义"),
        "返回值变量缺失: {kinds:?}"
    );
}

#[test]
fn top_level_return_is_ignored() {
    let project = project(
        "",
        &[("start.txt", "return:5;\n:after -when=(missing==1);")],
    );
    let kinds = diagnostics(&project);

    // 顶层场景的 return 无调用帧可弹, 执行继续
    assert!(
        has_error(&kinds, "变量 `missing` 未定义"),
        "顶层 return 未忽略: {kinds:?}"
    );
}

// -------- 嵌套调用 --------

#[test]
fn nested_calls_return_in_order() {
    let project = project(
        "",
        &[
            (
                "start.txt",
                "callScene:a.txt -writeReturnTo=ra;\n:ra_ok -when=(1/(ra-1)>0);",
            ),
            (
                "a.txt",
                "callScene:b.txt -writeReturnTo=rb;\n:rb_ok -when=(1/(rb-2)>0);\nreturn:1;",
            ),
            ("b.txt", "return:2;"),
        ],
    );
    let kinds = diagnostics(&project);

    // b 的返回值写入 a 的 rb, a 的返回值写入 start 的 ra
    assert!(
        has_error(&kinds, "除数不能为零"),
        "嵌套返回值 rb=2 未写回: {kinds:?}"
    );
    assert!(
        has_error(&kinds, "除数不能为零"),
        "嵌套返回值 ra=1 未写回: {kinds:?}"
    );
}

// -------- 调用栈深度上限 --------

#[test]
fn call_stack_depth_limit() {
    // 构造 callScene 链: start -> c0 -> c1 -> ... -> c64 -> c65
    let mut scenes = HashMap::new();
    for i in 0..65 {
        scenes.insert(
            format!("c{i}.txt"),
            Scene::from_str(format!("callScene:c{}.txt;", i + 1)),
        );
    }
    scenes.insert("c65.txt".to_string(), Scene::from_str("end;"));
    scenes.insert(
        "start.txt".to_string(),
        Scene::from_str("callScene:c0.txt;"),
    );

    let project = TestProject {
        config: Config::default(),
        scenes,
    };
    let kinds = diagnostics(&project);

    assert!(
        kinds.iter().any(|kind| matches!(
            kind,
            DiagnosticKind::Stopped(StopReason::SceneStackOverflow(64))
        )),
        "调用栈深度上限未触发: {kinds:?}"
    );
}
